#include <stdlib.h>
#include <string.h>

#if defined(__AVX512F__)
#define VL 16
#define MR 8
#define KC 256
#else
#define VL 8
#define MR 6
#define KC 384
#endif
#define NR (2 * VL)
#define MC (MR * 8)
#define NCB (NR * 8 > 128 ? 128 : NR * 8)

typedef float vf __attribute__((vector_size(VL * 4), aligned(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int first)
{
    vf acc[MR][2];
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) {
        acc[i][0] = (vf){0};
        acc[i][1] = (vf){0};
        __builtin_prefetch(c + i * ldc, 1, 3);
        __builtin_prefetch(c + i * ldc + NR - 1, 1, 3);
    }
#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VL);
        __builtin_prefetch(b + 8 * NR, 0, 3);
        __builtin_prefetch(a + 8 * MR, 0, 3);
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float ai = a[i];
            acc[i][0] += ai * b0;
            acc[i][1] += ai * b1;
        }
        a += MR;
        b += NR;
    }
    if (first) {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) = acc[i][0];
            *(vfu *)(c + i * ldc + VL) = acc[i][1];
        }
    } else {
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            *(vfu *)(c + i * ldc) += acc[i][0];
            *(vfu *)(c + i * ldc + VL) += acc[i][1];
        }
    }
}

static void pack_a_panel(const float *A, int n, int i0, int mr, int p0, int kc, float *ap)
{
    int i;
    for (i = 0; i < mr; i++) {
        const float *src = A + (size_t)(i0 + i) * n + p0;
        for (int k = 0; k < kc; k++)
            ap[k * MR + i] = src[k];
    }
    for (; i < MR; i++)
        for (int k = 0; k < kc; k++)
            ap[k * MR + i] = 0.0f;
}

static void pack_b_panel(const float *B, int n, int p0, int kc, int j0, int nr, float *bp)
{
    if (nr == NR) {
        for (int k = 0; k < kc; k++)
            memcpy(bp + (size_t)k * NR, B + (size_t)(p0 + k) * n + j0, NR * sizeof(float));
        return;
    }
    for (int k = 0; k < kc; k++) {
        const float *src = B + (size_t)(p0 + k) * n + j0;
        float *dst = bp + (size_t)k * NR;
        int j;
        for (j = 0; j < nr; j++) dst[j] = src[j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

static float *g_ap = NULL, *g_bp = NULL;
static size_t g_asz = 0, g_bsz = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) / 4096 * 4096;
    p = (float *)aligned_alloc(64, need);
    *cap = need;
    return p;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    int npanA = (n + MR - 1) / MR;
    int npanB = (n + NR - 1) / NR;
    g_ap = grow(g_ap, &g_asz, (size_t)npanA * MR * KC * sizeof(float));
    g_bp = grow(g_bp, &g_bsz, (size_t)npanB * NR * KC * sizeof(float));
    float *ap = g_ap, *bp = g_bp;

    int nib = (n + MC - 1) / MC;
    int njb = (n + NCB - 1) / NCB;
    int ntask = nib * njb;

#pragma omp parallel
    {
        float tile[MR * NR] __attribute__((aligned(64)));
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

#pragma omp for schedule(static)
            for (int q = 0; q < npanA + npanB; q++) {
                if (q < npanA) {
                    int i0 = q * MR;
                    int mr = n - i0 < MR ? n - i0 : MR;
                    pack_a_panel(A, n, i0, mr, pc, kc, ap + (size_t)q * kc * MR);
                } else {
                    int qb = q - npanA;
                    int j0 = qb * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    pack_b_panel(B, n, pc, kc, j0, nr, bp + (size_t)qb * kc * NR);
                }
            }

#pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntask; t++) {
                int ib = t / njb, jb = t % njb;
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int jstart = jb * NCB;
                int jend = jstart + NCB < n ? jstart + NCB : n;
                for (int j = jstart; j < jend; j += NR) {
                    int nr = n - j < NR ? n - j : NR;
                    const float *bpan = bp + (size_t)(j / NR) * kc * NR;
                    for (int i = 0; i < mc; i += MR) {
                        int mr = mc - i < MR ? mc - i : MR;
                        const float *apan = ap + (size_t)((i0 + i) / MR) * kc * MR;
                        float *cp = C + (size_t)(i0 + i) * n + j;
                        if (mr == MR && nr == NR) {
                            kernel(kc, apan, bpan, cp, n, first);
                        } else {
                            kernel(kc, apan, bpan, tile, NR, 1);
                            for (int ii = 0; ii < mr; ii++) {
                                float *crow = cp + (size_t)ii * n;
                                const float *trow = tile + ii * NR;
                                if (first)
                                    for (int jj = 0; jj < nr; jj++) crow[jj] = trow[jj];
                                else
                                    for (int jj = 0; jj < nr; jj++) crow[jj] += trow[jj];
                            }
                        }
                    }
                }
            }
        }
    }
}
